    const moveFish = () => {
      const now = Date.now()
      const cx = POND_W / 2
      const cy = POND_H / 2
      const rx = POND_W / 2 - 26
      const ry = POND_H / 2 - 24
      for (const f of fish) {
        if (f.leaving) continue
        if (now - f.born >= f.life) {
          f.leaving = true
          f.el.classList.add('dshp-whale-fish-leave')
